          sourceReference
          presentedName
          brandedPromise {
            handle
            name
          }
        }
        assignedLocation {
          address1
          address2
          city
          countryCode
          location {
            id
          }
          name
          phone
          province
          zip
        }
        merchantRequests(first: 250) {
          nodes {
